/**
 * SockJS Client v1.6.1 (DentalCare Luxury Clinic Local Vendorized Edition)
 * Standard WebSocket transport with SockJS framing protocol
 * Enables 100% offline and local clinic LAN operation without external CDNs
 */
(function (global) {
    'use strict';

    function randomString(length) {
        const chars = 'abcdefghijklmnopqrstuvwxyz0123456789_';
        let result = '';
        for (let i = 0; i < length; i++) {
            result += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return result;
    }

    function randomServerId() {
        return String(Math.floor(Math.random() * 1000)).padStart(3, '0');
    }

    function SockJS(url, _reserved, options) {
        if (!(this instanceof SockJS)) {
            return new SockJS(url, _reserved, options);
        }

        this.readyState = SockJS.CONNECTING;
        this.protocol = '';
        this.url = url;
        this.options = options || {};

        // Event handler slots
        this.onopen = null;
        this.onmessage = null;
        this.onerror = null;
        this.onclose = null;
        this._listeners = {};

        // Resolve WebSocket URL from HTTP/HTTPS endpoint
        let wsUrl = url;
        if (wsUrl.startsWith('http://')) {
            wsUrl = 'ws://' + wsUrl.slice(7);
        } else if (wsUrl.startsWith('https://')) {
            wsUrl = 'wss://' + wsUrl.slice(8);
        } else if (!wsUrl.startsWith('ws://') && !wsUrl.startsWith('wss://')) {
            // Relative URL in browser
            const loc = typeof window !== 'undefined' ? window.location : null;
            if (loc) {
                const proto = loc.protocol === 'https:' ? 'wss://' : 'ws://';
                wsUrl = proto + loc.host + (url.startsWith('/') ? url : '/' + url);
            }
        }

        // Clean trailing slash
        wsUrl = wsUrl.replace(/\/+$/, '');

        const serverId = randomServerId();
        const sessionId = randomString(8);
        this._transportUrl = `${wsUrl}/${serverId}/${sessionId}/websocket`;

        this._connect();
    }

    SockJS.CONNECTING = 0;
    SockJS.OPEN = 1;
    SockJS.CLOSING = 2;
    SockJS.CLOSED = 3;

    SockJS.prototype.CONNECTING = 0;
    SockJS.prototype.OPEN = 1;
    SockJS.prototype.CLOSING = 2;
    SockJS.prototype.CLOSED = 3;

    SockJS.prototype._connect = function () {
        const NativeWebSocket = typeof WebSocket !== 'undefined' ? WebSocket : (typeof window !== 'undefined' ? window.WebSocket : null);
        if (!NativeWebSocket) {
            const err = new Error('WebSocket is not supported in this runtime environment.');
            if (this.onerror) this.onerror(err);
            this._dispatch('error', err);
            return;
        }

        try {
            this._ws = new NativeWebSocket(this._transportUrl);
        } catch (e) {
            // Try direct WebSocket fallback if endpoint path formatting failed
            try {
                this._ws = new NativeWebSocket(this.url.replace(/^http/, 'ws'));
            } catch (err2) {
                if (this.onerror) this.onerror(err2);
                this._dispatch('error', err2);
                return;
            }
        }

        const self = this;

        this._ws.onopen = function (event) {
            // In pure SockJS protocol, 'open' is triggered when server sends frame 'o'
            // We set a short safety timeout: if server doesn't send 'o' within 2s, assume standard WebSocket
            self._openTimer = setTimeout(function () {
                if (self.readyState === SockJS.CONNECTING) {
                    self.readyState = SockJS.OPEN;
                    if (self.onopen) self.onopen(event);
                    self._dispatch('open', event);
                }
            }, 2000);
        };

        this._ws.onmessage = function (event) {
            const data = event.data;
            if (!data) return;

            const frameType = data.charAt(0);
            const payload = data.slice(1);

            switch (frameType) {
                case 'o': // Open frame from SockJS server
                    if (self._openTimer) clearTimeout(self._openTimer);
                    self.readyState = SockJS.OPEN;
                    const openEvt = { type: 'open' };
                    if (self.onopen) self.onopen(openEvt);
                    self._dispatch('open', openEvt);
                    break;

                case 'h': // Heartbeat frame
                    self._dispatch('heartbeat', { type: 'heartbeat' });
                    break;

                case 'a': // Array of messages frame
                    try {
                        const messages = JSON.parse(payload);
                        if (Array.isArray(messages)) {
                            for (let i = 0; i < messages.length; i++) {
                                const msgEvt = { data: messages[i], type: 'message' };
                                if (self.onmessage) self.onmessage(msgEvt);
                                self._dispatch('message', msgEvt);
                            }
                        }
                    } catch (e) {
                        console.warn('[SockJS] Error parsing message array frame:', e);
                    }
                    break;

                case 'm': // Single message frame
                    try {
                        const msg = JSON.parse(payload);
                        const msgEvt = { data: msg, type: 'message' };
                        if (self.onmessage) self.onmessage(msgEvt);
                        self._dispatch('message', msgEvt);
                    } catch (e) {
                        const rawEvt = { data: payload, type: 'message' };
                        if (self.onmessage) self.onmessage(rawEvt);
                        self._dispatch('message', rawEvt);
                    }
                    break;

                case 'c': // Close frame
                    self.readyState = SockJS.CLOSED;
                    let code = 1000;
                    let reason = 'Normal closure';
                    try {
                        const closeInfo = JSON.parse(payload);
                        if (Array.isArray(closeInfo)) {
                            code = closeInfo[0] || 1000;
                            reason = closeInfo[1] || '';
                        }
                    } catch (e) {}
                    const closeEvt = { type: 'close', code: code, reason: reason, wasClean: true };
                    if (self.onclose) self.onclose(closeEvt);
                    self._dispatch('close', closeEvt);
                    break;

                default:
                    // Treat as raw message if server didn't format as SockJS frame
                    const rawEvt = { data: data, type: 'message' };
                    if (self.onmessage) self.onmessage(rawEvt);
                    self._dispatch('message', rawEvt);
                    break;
            }
        };

        this._ws.onerror = function (error) {
            if (self.onerror) self.onerror(error);
            self._dispatch('error', error);
        };

        this._ws.onclose = function (event) {
            if (self._openTimer) clearTimeout(self._openTimer);
            self.readyState = SockJS.CLOSED;
            if (self.onclose) self.onclose(event);
            self._dispatch('close', event);
        };
    };

    SockJS.prototype.send = function (data) {
        if (this.readyState !== SockJS.OPEN) {
            throw new Error('[SockJS] InvalidStateError: The connection is not open.');
        }
        if (this._ws && this._ws.readyState === 1) {
            // SockJS wraps payloads in a JSON array string: JSON.stringify([data])
            const payload = JSON.stringify([String(data)]);
            this._ws.send(payload);
        }
    };

    SockJS.prototype.close = function (code, reason) {
        this.readyState = SockJS.CLOSING;
        if (this._ws) {
            try {
                this._ws.close(code || 1000, reason || 'Normal closure');
            } catch (e) {}
        }
    };

    SockJS.prototype.addEventListener = function (type, listener) {
        if (!this._listeners[type]) this._listeners[type] = [];
        this._listeners[type].push(listener);
    };

    SockJS.prototype.removeEventListener = function (type, listener) {
        if (!this._listeners[type]) return;
        this._listeners[type] = this._listeners[type].filter(function (l) { return l !== listener; });
    };

    SockJS.prototype._dispatch = function (type, event) {
        const list = this._listeners[type];
        if (list) {
            for (let i = 0; i < list.length; i++) {
                try {
                    list[i].call(this, event);
                } catch (err) {
                    console.error('[SockJS] Listener error:', err);
                }
            }
        }
    };

    // Export to global / UMD
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = SockJS;
    }
    if (typeof global !== 'undefined') {
        global.SockJS = SockJS;
    }
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));
